package android.graphics; public final class Rect { public int left, top, right, bottom; public Rect() {} public Rect(int l, int t, int r, int b) { left=l; top=t; right=r; bottom=b; } public Rect(Rect r) { this(r.left, r.top, r.right, r.bottom); } public void set(Rect r) { left=r.left; top=r.top; right=r.right; bottom=r.bottom; } public boolean isEmpty() { return left>=right || top>=bottom; } public int width() { return right - left; } public int height() { return bottom - top; } }
